import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

type Upload = { name: string; mimeType: string; buffer: Buffer };

const cases: { label: string; file: () => Upload; kind: string; status: number; code: string }[] = [
  {
    label: "an empty file",
    file: () => ({ name: "empty.txt", mimeType: "text/plain", buffer: Buffer.alloc(0) }),
    kind: "w9",
    status: 422,
    code: "empty_file",
  },
  {
    label: "a file of exactly 10 MiB + 1",
    file: () => ({ name: "big.txt", mimeType: "text/plain", buffer: Buffer.alloc(TEN_MIB + 1, "x") }),
    kind: "w9",
    status: 413,
    code: "file_too_large",
  },
  {
    label: "a .exe file",
    file: () => ({ name: "tool.exe", mimeType: "application/octet-stream", buffer: Buffer.from("MZ") }),
    kind: "w9",
    status: 415,
    code: "unsupported_type",
  },
  {
    label: "a valid text file",
    file: () => ({ name: "w9.txt", mimeType: "text/plain", buffer: fs.readFileSync(sample("w9.txt")) }),
    kind: "passport",
    status: 422,
    code: "validation_error",
  },
];

test.describe("Upload vendor documents: reject invalid uploads", () => {
  for (const c of cases) {
    test(`uploading ${c.label} as kind \"${c.kind}\" is rejected with ${c.status} ${c.code}`, { tag: "@DOC-04" }, async ({ apiAs }) => {
      // Background: signed in as member, a vendor in status draft
      const member = await apiAs("member");
      const create = await member.post("/api/vendors", {
        data: { name: uniqueName("Doc04 Vendor"), category: "software", contact_email: "ap@acme-supplies.com" },
      });
      expect(create.status(), await create.text()).toBe(201);
      const vendor = await create.json();
      expect(vendor.status).toBe("draft");

      // When
      const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: { kind: c.kind, file: c.file() },
      });

      // Then
      const body = await res.text();
      expect(res.status(), body).toBe(c.status);
      expect(JSON.parse(body).error.code, body).toBe(c.code);

      // Nothing was stored for the vendor
      const docs = await member.get(`/api/vendors/${vendor.id}/documents`);
      expect(docs.status(), await docs.text()).toBe(200);
      expect(await docs.json()).toEqual([]);
    });
  }
});
